import{bV as a,aL as t,u as s,G as i}from"./chunks/framework.DvBUyM1S.js";const k=JSON.parse('{"title":"New API 用量与 token 统计落地配置（看板 / 倍率 / 查询 API / 长期留存）","description":"","frontmatter":{"id":"PB-20260907-002","type":"playbook","title":"New API 用量与 token 统计落地配置（看板 / 倍率 / 查询 API / 长期留存）","tags":["new-api","token-stats","billing","ai-gateway"],"status":"draft","source":"web-collected:2026-09-07","created":"2026-09-07T00:00:00.000Z","updated":"2026-09-07T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/new-api-token-usage-stats.md","filePath":"playbooks/new-api-token-usage-stats.md"}'),o={name:"playbooks/new-api-token-usage-stats.md"};function n(l,e,d,h,r,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="new-api-用量与-token-统计落地配置" tabindex="-1">New API 用量与 token 统计落地配置 <a class="header-anchor" href="#new-api-用量与-token-统计落地配置" aria-label="Permalink to &quot;New API 用量与 token 统计落地配置&quot;">​</a></h1><h2 id="_0-先分清两个口径" tabindex="-1">0. 先分清两个口径 <a class="header-anchor" href="#_0-先分清两个口径" aria-label="Permalink to &quot;0. 先分清两个口径&quot;">​</a></h2><ul><li><strong>原始 token 数</strong>：日志里的 <code>prompt_tokens</code> / <code>completion_tokens</code>，来自上游 usage。</li><li><strong>额度 quota（计费单位）</strong>：New API 内部结算单位，<code>1 USD = 500,000 quota</code>。看板/账单看的是 quota。</li></ul><h2 id="_1-开箱即用的统计入口" tabindex="-1">1. 开箱即用的统计入口 <a class="header-anchor" href="#_1-开箱即用的统计入口" aria-label="Permalink to &quot;1. 开箱即用的统计入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>路径</th><th>能看到什么</th></tr></thead><tbody><tr><td>数据看板</td><td><code>/console</code>（管理员）</td><td>全平台消耗趋势折线图、各用户消耗占比，悬停看每日数值</td></tr><tr><td>日志与统计</td><td><code>/console/log</code>（管理员）</td><td>全平台调用记录，可按时间/用户名/模型/渠道/令牌名筛选；管理员视图多「用户名」「渠道名」两列</td></tr><tr><td>使用日志</td><td>用户控制台</td><td>自己账号的请求记录；另有绘图日志、任务日志（视频/音乐等异步任务，含退款状态）</td></tr></tbody></table><h2 id="_2-先把倍率配准-否则统计数字没意义" tabindex="-1">2. 先把倍率配准，否则统计数字没意义 <a class="header-anchor" href="#_2-先把倍率配准-否则统计数字没意义" aria-label="Permalink to &quot;2. 先把倍率配准，否则统计数字没意义&quot;">​</a></h2><p>系统设置 → <strong>倍率设置</strong>（模型倍率 ModelRatio / 补全倍率 CompletionRatio / 分组倍率 GroupRatio），支持 JSON 或可视化编辑、一键上游同步。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>额度消耗 = (输入 tokens + 输出 tokens × 补全倍率) × 模型倍率 × 分组倍率</span></span>
<span class="line"><span>按次计费：额度 = 模型固定价 × 分组倍率 × 500,000</span></span></code></pre></div><ul><li>示例：gpt-4o 模型倍率 1.25、补全倍率 4（输出单价是输入 4 倍）；gpt-4o-mini 0.075 / 4。</li><li>未配置倍率的模型：自用模式按默认 37.5 计，商务模式直接报「未配置倍率或价格」。</li><li>计费机制是<strong>预扣 + 后扣差额调整</strong>：按估算 token 预扣，结束后按实际 token 重算并自动补退。</li></ul><h2 id="_3-程序化查询" tabindex="-1">3. 程序化查询 <a class="header-anchor" href="#_3-程序化查询" aria-label="Permalink to &quot;3. 程序化查询&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">your-newapi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/api/usage/token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NEWAPI_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>返回 <code>total_granted</code> / <code>total_used</code> / <code>total_available</code> / <code>unlimited_quota</code> / <code>model_limits</code> / <code>expires_at</code>（-1 归一化为 0）。 注：<code>sk-</code> 前缀可有可无；缺 Authorization 返回 401，令牌失效返回 <code>token not found</code>。</p><h2 id="_4-准确性与排障" tabindex="-1">4. 准确性与排障 <a class="header-anchor" href="#_4-准确性与排障" aria-label="Permalink to &quot;4. 准确性与排障&quot;">​</a></h2><ul><li>token 数取决于<strong>上游是否返回 usage</strong>：流式场景需要上游支持 usage 回传（OpenAI 系需 <code>stream_options.include_usage</code>），否则只能按估算计费 → 用日志里的 token 字段抽样核对。</li><li>日志表增长很快：SQLite 单文件会膨胀拖慢查询；有对账/多节点需求改 MySQL，并定期归档。</li><li>数据量大时按用户/模型/渠道维度用日志筛选，别全表扫描。</li></ul><h2 id="_5-外部看板-可选" tabindex="-1">5. 外部看板（可选） <a class="header-anchor" href="#_5-外部看板-可选" aria-label="Permalink to &quot;5. 外部看板（可选）&quot;">​</a></h2><ul><li><code>newapi-stats</code>（VS Code 扩展）：配 baseUrl + userId + session cookie，实时显示余额、今日/总消耗、请求数、提示/完成 token；转换因子默认 500000。</li><li>直连数据库查 <code>logs</code> 表（<code>prompt_tokens</code> / <code>completion_tokens</code> / <code>quota</code> / <code>model_name</code> / <code>channel</code> / <code>use_time</code>；具体字段以实际版本 schema 为准）做自定义报表。</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li>PB-20260907-001（AI 网关选型对比：CLIProxyAPI vs New API vs Sub2API）</li></ul>`,18)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
